with base as (select *, concat(city, ' - ', store_name) as city_store_name, trim(city) as clean_city, coalesce(region, 'N/A') as region_clean from stores where opened_date > to_date('2023-08-08') and region is not null), not_flagged as (select s.* from base s where not exists (select 1 from inventory x where x.store_id = s.id and x.last_restock <= s.opened_date)), latest_match as (select s.*, top1.quantity, top1.last_restock from not_flagged s left join lateral (select c.quantity, c.last_restock from inventory c where c.store_id = s.id and c.last_restock <= s.opened_date order by c.last_restock desc, c.id desc limit 1) top1 on true), matched_keys as (select region, id from latest_match except select region, id from stores where city not in ('Tokyo', 'Chiang Mai')), kept_rows as (select s.* from latest_match s inner join matched_keys k on s.region = k.region and s.id = k.id), summary as (select date_trunc('quarter', opened_date) as quarter_start, city, round(avg(sqft), 2) as avg_sqft, sum(sqft) as total_sqft, avg(quantity) filter (where city = 'Tokyo') as tokyo_avg_quantity, approx_percentile(quantity, 0.5) as quantity_p50, bit_and(sqft) as sqft_bit_and, round(sum(sqft) / nullif(count(case when region = 'South' then 1 end), 0), 2) as sqft_per_south from kept_rows group by cube (date_trunc('quarter', opened_date), city)) select city, avg_sqft, total_sqft, tokyo_avg_quantity, sqft_bit_and, sqft_per_south, case when city rlike '^(New York|London)$' then 'PRIORITY' else 'GROUP_B' end as city_zone from summary order by sqft_bit_and desc nulls last;
